<?php
namespace App\Policies; use App\Domain\Tenancy\TenantContext; use App\Models\{PartnerPayoutRequest,User}; final class PartnerPayoutRequestPolicy{public function viewAny(User$u):bool{/* UI audit 2026-09-27: was any active member */return$u->memberships()->where('status','ACTIVE')->exists()&&($u->hasPermission('commission.read')||$u->hasPermission('statements.read'));}public function view(User$u,PartnerPayoutRequest$m):bool{return$m->tenant_id===app(TenantContext::class)->id()&&$this->viewAny($u);}public function create(User$u):bool{return$this->viewAny($u);}public function update(User$u,PartnerPayoutRequest$m):bool{return false;}public function delete(User$u,PartnerPayoutRequest$m):bool{return false;}}
